const healthStorageKey='plp-health-summary-v1';
const healthFile=document.getElementById('garminFile'); const healthStatus=document.getElementById('healthStatus'); const healthReset=document.getElementById('healthReset'); const healthDemo=document.getElementById('healthDemo');
      let healthSummary=null; let healthImportBusy=false;
      const formatInteger=value=>value===null||value===undefined?'—':Math.round(value).toLocaleString('fr-FR');
      function formatDuration(minutes){if(minutes===null||minutes===undefined)return '—';const rounded=Math.max(0,Math.round(minutes));return `${Math.floor(rounded/60)} h ${String(rounded%60).padStart(2,'0')}`}
      function paintHealth(summary){healthSummary=summary&&Object.keys(summary).length?summary:null;const steps=healthSummary?.steps;const goal=healthSummary?.stepGoal;const percent=steps!==undefined&&goal?Math.min(100,Math.round(steps/goal*100)):null;document.getElementById('stepsRing').style.setProperty('--health-progress',`${percent||0}%`);document.getElementById('stepsPercent').textContent=percent===null?'—':`${percent}%`;document.getElementById('stepsValue').textContent=formatInteger(steps);document.getElementById('stepsNote').textContent=goal?`Objectif : ${formatInteger(goal)} pas`:'Objectif non importé';document.getElementById('sleepValue').textContent=formatDuration(healthSummary?.sleepMinutes);document.getElementById('sleepNote').textContent=healthSummary?.sleepMinutes!==undefined?'Sommeil total':'Durée non importée';document.getElementById('caloriesValue').textContent=healthSummary?.activeCalories!==undefined?`${formatInteger(healthSummary.activeCalories)} kcal`:'—';document.getElementById('caloriesNote').textContent=healthSummary?.totalCalories!==undefined?`Total : ${formatInteger(healthSummary.totalCalories)} kcal`:'Total non importé';document.getElementById('heartValue').textContent=healthSummary?.restingHeartRate!==undefined?`${formatInteger(healthSummary.restingHeartRate)} bpm`:'—';document.getElementById('heartNote').textContent=healthSummary?.averageHeartRate!==undefined?`Moyenne : ${formatInteger(healthSummary.averageHeartRate)} bpm`:'Moyenne non importée';document.getElementById('stressValue').textContent=healthSummary?.stressAverage!==undefined?`${formatInteger(healthSummary.stressAverage)} / 100`:'—';document.getElementById('hrvNote').textContent=healthSummary?.hrvMs!==undefined?`VFC : ${formatInteger(healthSummary.hrvMs)} ms`:'VFC non importée';const activity=healthSummary?.latestActivity;document.getElementById('healthActivity').textContent=activity?`${activity.name}${activity.durationMinutes?` · ${formatInteger(activity.durationMinutes)} min`:''}${activity.distanceKm?` · ${String(activity.distanceKm).replace('.',',')} km`:''}`:'Aucune activité importée';healthReset.hidden=!healthSummary;}
      function saveHealthLocal(summary){try{if(summary)localStorage.setItem(healthStorageKey,JSON.stringify(summary));else localStorage.removeItem(healthStorageKey)}catch(error){}}
